"""Andrey GIN solution adapter for data generated by latent variables and their indicators.

Calls ``andrey.gin(X, alpha=0.05)``, Andrey's default, and returns its clusters in the latent order
it reports (``metadata["causal_order"]``), and the clusters it left unordered
(``metadata["unordered"]``), in the native form of :mod:`~andrey_bench.adapters.gin_convert`.
"""

from __future__ import annotations

from typing import Any, Mapping

import numpy as np

from andrey_bench.adapters.gin_convert import encode_clusters, latent_dag

_DEFAULTS = {"alpha": 0.05}


def _andrey_version() -> str:
    """The installed Andrey version (distribution metadata, else the module attribute)."""
    from importlib import metadata

    try:
        return metadata.version("andrey")
    except metadata.PackageNotFoundError:  # editable/dev checkout with no dist metadata
        import andrey

        return getattr(andrey, "__version__", "unknown")


class AndreyGIN:
    """Solution adapter for Andrey's GIN.

    Satisfies :class:`andrey_bench.contracts.SolutionAdapter`.
    """

    name: str = "andrey.gin.numpy"
    package: str = "andrey"
    package_version: str = _andrey_version()
    backend: str = "numpy"
    mode: str = "serial"
    algorithm: str = "gin"
    output_type: str = "dag"

    def setup(self) -> None:
        """Import Andrey and its GIN implementation before timing; see `contracts.SetupAdapter`."""
        import andrey  # noqa: F401
        from andrey.latent.gin import gin_structure  # noqa: F401

    def params(self) -> dict[str, Any]:
        """Return the significance level of the test that finds the clusters."""
        return dict(_DEFAULTS)

    def fit(self, data: np.ndarray, params: Mapping[str, Any]) -> np.ndarray:
        """Run Andrey GIN; return its clusters and their order. The only timed region."""
        import andrey

        X = np.asarray(data, dtype=np.float64)
        out = andrey.gin(X, alpha=float({**_DEFAULTS, **params}["alpha"]))
        meta = out.metadata
        return encode_clusters(meta["causal_order"], meta["unordered"], X.shape[1])

    def to_structure(self, native: np.ndarray) -> Any:
        """Build the latent DAG from the clusters outside the timed region."""
        return latent_dag(native)
